@router.get("/", response_model=List[MessageOut])
def list_messages(
    job_id: int | None = None,
    is_internal: bool | None = None,
    skip: int = 0,
    limit: int = 100,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user),
):
    query = db.query(Message)

    if user.role == UserRole.customer:
        query = query.filter(Message.is_internal == False)
        cp = db.query(CustomerProfile).filter(CustomerProfile.user_id == user.id).first()
        if cp:
            job_ids = db.query(Job.id).filter(Job.customer_id == cp.id)
            query = query.filter(
                (Message.job_id.in_(job_ids)) | (Message.recipient_id == user.id) | (Message.author_id == user.id)
            )
        else:
            query = query.filter((Message.recipient_id == user.id) | (Message.author_id == user.id))
    elif user.role == UserRole.field_worker:
        from app.models import WorkerProfile
        wp = db.query(WorkerProfile).filter(WorkerProfile.user_id == user.id).first()
        if wp:
            job_ids = db.query(Job.id).filter(Job.assigned_worker_id == wp.id)
            query = query.filter(
                (Message.job_id.in_(job_ids)) | (Message.recipient_id == user.id) | (Message.author_id == user.id)
            )
        else:
            query = query.filter((Message.recipient_id == user.id) | (Message.author_id == user.id))

    if job_id:
        query = query.filter(Message.job_id == job_id)
    if is_internal is not None:
        query = query.filter(Message.is_internal == is_internal)

    return query.order_by(Message.created_at.desc()).offset(skip).limit(limit).all()


